// UrbanFlow AI — Member 2: Complaint Intake Validation & Normalization
const inputData = $input.first().json;
const raw = inputData.body || inputData;

// 1. Validate description (required, must be non-empty string after trimming)
const rawDesc = raw.description;
if (rawDesc === null || rawDesc === undefined || typeof rawDesc !== 'string') {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      message: "The complaint description is required and must be text.",
      http_status: 400
    }
  }];
}

const trimmedDesc = rawDesc.trim();
if (trimmedDesc.length === 0) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      message: "The complaint description cannot be empty.",
      http_status: 400
    }
  }];
}

// 2. Validate source (one of citizen_complaint, simulated_sensor, admin)
const allowedSources = ['citizen_complaint', 'simulated_sensor', 'admin'];
const rawSource = raw.source || 'citizen_complaint';
if (!allowedSources.includes(rawSource)) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      message: `Invalid source '${rawSource}'. Allowed sources: ${allowedSources.join(', ')}.`,
      http_status: 400
    }
  }];
}

// 3. Handle coordinates (numeric or null, never infer from image/text)
let lat = (raw.latitude !== undefined && raw.latitude !== null) ? Number(raw.latitude) : null;
let lon = (raw.longitude !== undefined && raw.longitude !== null) ? Number(raw.longitude) : null;
if (isNaN(lat)) lat = null;
if (isNaN(lon)) lon = null;
const hasCoordinates = (lat !== null && lon !== null);

// 4. Generate RFC-4122 v4 compliant UUID if not provided
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const complaintId = raw.complaint_id || generateUUID();
const eventId = raw.event_id || generateUUID();
const now = new Date().toISOString();

return [{
  json: {
    valid: true,
    complaint_id: complaintId,
    event_id: eventId,
    citizen_name: raw.citizen_name || 'Demo Citizen',
    contact: raw.contact || null,
    description: trimmedDesc,
    category: raw.category || null,
    image_url: raw.image_url || null,
    latitude: lat,
    longitude: lon,
    has_coordinates: hasCoordinates,
    location_text: raw.location_text || (hasCoordinates ? `${lat}, ${lon}` : 'Location unprovided'),
    source: rawSource,
    created_at: now,
    updated_at: now
  }
}];

// UrbanFlow AI — Category Classification & Shared Priority Rules
const item = $input.first().json;
const desc = (item.description || '').toLowerCase();
const allowedDepartments = ['traffic', 'safety', 'waste', 'environment', 'water', 'energy', 'general'];

let category = item.category ? item.category.toLowerCase() : null;

// 1. Classification into exactly one allowed department
if (!allowedDepartments.includes(category)) {
  if (desc.match(/\b(active fire|life threat|explosion|theft|assault|crime|safety|harassment|vandalism|weapon|suspicious|violence|emergency|structural collapse)\b/)) {
    category = 'safety';
  } else if (desc.match(/\b(traffic|traffic jam|congestion|traffic lights?|traffic signals?|road block|pothole|car crash|accident|intersection|lane|speeding|pedestrian crossing)\b/)) {
    category = 'traffic';
  } else if (desc.match(/\b(water|pipe|leak|drain|drainage|waterlogging|flooding|supply|sewage|sewer|contamination|burst)\b/)) {
    category = 'water';
  } else if (desc.match(/\b(garbage|trash|bin|bins|waste|dump|rubbish|litter|sanitation|collection|recycling|debris)\b/)) {
    category = 'waste';
  } else if (desc.match(/\b(electricity|power|blackout|outage|street ?lights?|spark|wire|pole|transformer|voltage|short circuit)\b/)) {
    category = 'energy';
  } else if (desc.match(/\b(air quality|pollution|smoke|smog|aqi|noise|odor|odour|chemical|toxic|dust|tree falling|emission)\b/)) {
    category = 'environment';
  } else {
    category = 'general';
  }
}

// 2. Shared Priority Rules (Section 4.3):
// - critical: explicitly indicates an immediate threat to life or serious danger.
// - high: significant public safety or infrastructure concern, but no confirmed immediate life-threatening situation.
// - medium: service disruption or civic issue requiring timely attention.
// - low: minor issue with no stated immediate risk.
// - If evidence is insufficient or uncertain, use 'medium'.

let severity = 'medium';
if (desc.match(/\b(life threat|immediate danger|explosion|live wire touching|active fire|drowning|fatal|gas leak emergency|major collapse)\b/)) {
  severity = 'critical';
} else if (desc.match(/\b(major accident|broken water main|sparking transformer|severe flooding|hazardous waste|open manhole|high voltage wire)\b/)) {
  severity = 'high';
} else if (desc.match(/\b(overflow|leaking tap|flickering light|litter|pothole|delayed garbage|dirty road|illegal parking|congestion)\b/)) {
  severity = 'medium';
} else if (desc.match(/\b(cosmetic|faded paint|minor graffiti|mild smell|small puddle|routine query)\b/)) {
  severity = 'low';
} else {
  severity = 'medium';
}

item.category = category;
item.assigned_department = category;
item.severity = severity;
item.status = 'submitted'; // Citizen-facing initial status

return [{ json: item }];

// UrbanFlow AI — Format Record & Event Payload
const item = $input.first().json;

// Complaint record contract (Section 3.4)
const complaintRecord = {
  complaint_id: item.complaint_id,
  citizen_name: item.citizen_name,
  contact: item.contact,
  description: item.description,
  category: item.category,
  severity: item.severity,
  status: 'submitted',
  assigned_department: item.assigned_department,
  image_url: item.image_url,
  latitude: item.latitude,
  longitude: item.longitude,
  location_text: item.location_text,
  source: item.source,
  created_at: item.created_at,
  updated_at: item.updated_at
};

// Command agent event forwarding contract (Section 4.2 / Section 3.5)
const eventPayload = {
  event_id: item.event_id,
  complaint_id: item.complaint_id,
  source: item.source,
  department: item.assigned_department,
  category: item.category,
  description: item.description,
  location: {
    latitude: item.latitude,
    longitude: item.longitude,
    location_text: item.location_text
  },
  severity: item.severity,
  status: 'submitted',
  citizen_name: item.citizen_name,
  created_at: item.created_at
};

return [{
  json: {
    complaint_record: complaintRecord,
    event_payload: eventPayload
  }
}];
